import{_ as n,C as e,o as l,c as p,j as a,a as r,E as i,a2 as m}from"./chunks/framework.B-bxTAy7.js";const v=JSON.parse('{"title":"实验与仪器 · 板块主页","description":"电学手记的动手板块：万用表、示波器、焊接与搭电路、实验台与安全。先讲清楚每台仪器怎么接、接错会怎样、读数该怎么怀疑，再给出第一次上手的 3 小时清单。","frontmatter":{"title":"实验与仪器 · 板块主页","description":"电学手记的动手板块：万用表、示波器、焊接与搭电路、实验台与安全。先讲清楚每台仪器怎么接、接错会怎样、读数该怎么怀疑，再给出第一次上手的 3 小时清单。","outline":[2,3]},"headers":[],"relativePath":"lab/index.md","filePath":"lab/index.md","lastUpdated":1792603101000}'),o={name:"lab/index.md"};function h(c,s,d,g,u,b){const t=e("Meta");return l(),p("div",null,[s[0]||(s[0]=a("h1",{id:"实验与仪器",tabindex:"-1"},[r("实验与仪器 "),a("a",{class:"header-anchor",href:"#实验与仪器","aria-label":'Permalink to "实验与仪器"'},"​")],-1)),i(t,{time:"20 min",level:"指南",note:"先练「怎么读出真数」，再谈其他：四类基础仪器、面包板与洞洞板、安全底线，以及第一次上手的 3 小时清单"}),s[1]||(s[1]=m('<p>这个站里的其他章节都在「纸上」推电路：基尔霍夫定律、三要素法、工作点、波特图。这些推导可以全部在笔和纸上完成，所以一个常见的幻觉是「我懂了」，直到第一次把电阻插进面包板，发现 LED 不亮，才开始怀疑自己到底懂了什么。</p><p><strong>电学是少数几个「纸面正确、实物错误」出现频率极高的学科。</strong> 原因不神秘：纸上的电阻是 10 Ω 的实数，桌上的电阻是标称 10 Ω、公差 ±5%、两端各带一点导线电阻和接触电阻的实体；纸上的电源是理想电压源，桌上的可调电源有限流、有纹波、开关瞬间会过冲；纸上的电压是一条线，示波器上它会带 300 mV 的振铃。实验这一板块要解决的，不是「多做题」，而是<strong>让纸上的结论接受一条工具链的检验，并学会判断什么时候读数本身不可信</strong>。</p><h2 id="结论先行-这个板块要建立的六条直觉" tabindex="-1">结论先行：这个板块要建立的六条直觉 <a class="header-anchor" href="#结论先行-这个板块要建立的六条直觉" aria-label="Permalink to &quot;结论先行：这个板块要建立的六条直觉&quot;">​</a></h2><ol><li><strong>先接线，后上电；先预估，后读数。</strong> 动手前先用手算一个数量级：欧姆定律估电流、分压估电压。测出来和估算差一个量级，八成是接线或档位错了，不要急着相信仪器。</li><li><strong>测量的第一原则是「不要把被测对象变成别的东西」。</strong> 万用表电压档内阻 10 MΩ、电流档串入的分流电阻 10 mΩ、10X 探头并联 10 MΩ 与十几 pF 的电容，每一次探进去，电路都在变。误差的来源通常不是仪器精度，而是你接进去的那一下。</li><li><strong>四类基础仪器各看一个维度</strong>：万用表看<strong>静态量</strong>（在某一点的电压、流过的电流、断开的电阻），示波器看<strong>随时间变化的量</strong>（波形、上升时间、纹波、占空比），可调电源提供<strong>干净的、有边界条件的能量</strong>，信号源提供<strong>已知的、可控的激励</strong>。拿错维度去看，读数一定自相矛盾。</li><li><strong>面包板适合验证拓扑，洞洞板适合固化结果。</strong> 面包板的接触电阻从几毫欧到几欧都有，1 A 电流下可以产生零点几伏的压降；它也不是给开关电源、电机、高压信号准备的。</li><li><strong>安全不是「小心一点」，而是一条条可执行的规则</strong>：强电与弱电分区、保险丝与限流、电容放电、静电防护、接地与漏保。这些规则之所以写得那么死，是因为每条背后都有一次真实的爆炸或电击。</li><li><strong>出问题时，动作顺序比知识更重要</strong>：先断电、再放电、再检查、最后才分析。慌乱中的第一步往往决定了后果。</li></ol><h2 id="为什么电学必须动手" tabindex="-1">为什么电学必须动手 <a class="header-anchor" href="#为什么电学必须动手" aria-label="Permalink to &quot;为什么电学必须动手&quot;">​</a></h2><h3 id="纸上的三个「不可能」-桌上天天发生" tabindex="-1">纸上的三个「不可能」，桌上天天发生 <a class="header-anchor" href="#纸上的三个「不可能」-桌上天天发生" aria-label="Permalink to &quot;纸上的三个「不可能」，桌上天天发生&quot;">​</a></h3><ul><li><strong>接触电阻</strong>。面包板的弹簧片、杜邦线的插针、鳄鱼夹的齿，每个接点都有 10 mΩ 到 200 mΩ 的接触电阻。两个触点串起来，1 A 电流下就是 0.02 V 到 0.4 V 的压降，足以让一个 3.3 V 的系统读到 2.9 V，也足以让一个「应该有 5 V」的节点显示 4.6 V。纸上从来没有这个元件。</li><li><strong>电源不是理想的</strong>。可调电源从 0 直接跳到 12 V，输出电容充电那一下会有一个远超设定的电流尖峰与电压过冲；开关电源空载与满载的纹波差了好几倍。如果你的电路「一上电就烧」，第一嫌疑是电流，不是电压。</li><li><strong>元件有公差与温度系数</strong>。常见的碳膜电阻 ±5%，1/4 W；金属膜 ±1%，温漂 50 ppm/°C。五个 ±5% 的电阻做电桥，最坏失配能到 ±10%，用万用表逐个挑出来配对，是最便宜的「精度提升」。</li></ul><h3 id="动手能把哪几类误解一拳打掉" tabindex="-1">动手能把哪几类误解一拳打掉 <a class="header-anchor" href="#动手能把哪几类误解一拳打掉" aria-label="Permalink to &quot;动手能把哪几类误解一拳打掉&quot;">​</a></h3><table tabindex="0"><thead><tr><th>纸面结论</th><th>一台万用表就能验证的反问</th><th>对应页面</th></tr></thead><tbody><tr><td>串联电路各处电流相等</td><td>电流表串进不同位置，读数为什么不一样？</td><td><a href="./multimeter">万用表</a></td></tr><tr><td>电容「隔直通交」</td><td>直流稳态时电容两端电压表读多少？交流时用真有效值表读多少？</td><td><a href="./multimeter">万用表</a></td></tr><tr><td>二极管正偏压降恒为 0.7 V</td><td>换档位、换电流档测，0.7 V 稳得住吗？</td><td><a href="./multimeter">万用表</a></td></tr><tr><td>电源输出 5 V</td><td>示波器上一看，它的纹波是 5 mV 还是 50 mV？</td><td><a href="./oscilloscope">示波器</a></td></tr><tr><td>三极管放大倍数是 100</td><td>同一只管子在 1 mA 和 50 mA 下，β 还是 100 吗？</td><td><a href="./multimeter">万用表</a></td></tr></tbody></table><h2 id="四类基础仪器" tabindex="-1">四类基础仪器 <a class="header-anchor" href="#四类基础仪器" aria-label="Permalink to &quot;四类基础仪器&quot;">​</a></h2><h3 id="万用表-一支笔测四件事" tabindex="-1">万用表：一支笔测四件事 <a class="header-anchor" href="#万用表-一支笔测四件事" aria-label="Permalink to &quot;万用表：一支笔测四件事&quot;">​</a></h3><p>数字万用表（DMM）是唯一一台<strong>你可以在任何阶段、任何电路上安全投入使用</strong>的仪器（前提是档位选对）。它提供五个最常用的功能：直流/交流电压、直流/交流电流、电阻、通断（蜂鸣）、二极管与三极管测试。四个关键规格决定了它能回答什么问题：</p><table tabindex="0"><thead><tr><th>规格</th><th>典型值</th><th>什么时候会卡住你</th></tr></thead><tbody><tr><td>电压档输入阻抗</td><td>10 MΩ（部分档位 1 GΩ）</td><td>测高阻节点（&gt;1 MΩ）会被表本身分压吃掉</td></tr><tr><td>直流基本精度</td><td>0.5% ± 2 个字（入门）/ 0.05%（六位半）</td><td>测 10 mΩ 级采样电阻时完全不够用</td></tr><tr><td>电流档分流电阻</td><td>10 mΩ ~ 1 Ω（视量程）</td><td>串进电路后会改变工作点，小电流档尤其明显</td></tr><tr><td>真有效值</td><td>True RMS（非真有效值表按正弦估算）</td><td>测方波、可控硅调光、开关电源输出时读数会错得离谱</td></tr></tbody></table><p>细节（串并联接错会怎样、量程与分辨率、四线法、虚电与接触电阻误判）全部在<a href="./multimeter">万用表</a>里。</p><h3 id="示波器-把时间轴打开" tabindex="-1">示波器：把时间轴打开 <a class="header-anchor" href="#示波器-把时间轴打开" aria-label="Permalink to &quot;示波器：把时间轴打开&quot;">​</a></h3><p>万用表的读数是一段时间的平均，示波器给你的是<strong>随时间变化的波形</strong>。它回答的是万用表回答不了的四类问题：信号有没有过冲、振铃、毛刺？上升时间是多少？占空比稳定吗？纹波里是开关频率的成分还是工频干扰？</p><p>三个规格决定上限：<strong>带宽</strong>（典型 100 MHz 入门机）、<strong>采样率</strong>（1 GSa/s 级别）、<strong>存储深度</strong>。记住一条经验公式：示波器能真实呈现的最快上升时间约为</p><span class="katex-display"><span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML" display="block"><semantics><mrow><msub><mi>t</mi><mi>r</mi></msub><mo>≈</mo><mfrac><mn>0.35</mn><mi>B</mi></mfrac></mrow><annotation encoding="application/x-tex">t_r \\approx \\frac{0.35}{B} </annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7651em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal">t</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.1514em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.0278em;">r</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">≈</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:2.0074em;vertical-align:-0.686em;"></span><span class="mord"><span class="mopen nulldelimiter"></span><span class="mfrac"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:1.3214em;"><span style="top:-2.314em;"><span class="pstrut" style="height:3em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0502em;">B</span></span></span><span style="top:-3.23em;"><span class="pstrut" style="height:3em;"></span><span class="frac-line" style="border-bottom-width:0.04em;"></span></span><span style="top:-3.677em;"><span class="pstrut" style="height:3em;"></span><span class="mord"><span class="mord">0.35</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.686em;"><span></span></span></span></span></span><span class="mclose nulldelimiter"></span></span></span></span></span></span><p>100 MHz 带宽对应 3.5 ns。要用示波器测一个 10 ns 上升沿的信号，严格来说需要 0.35/10 ns = 35 MHz 以上的带宽，但「够用」意味着至少 3~5 倍余量。探头用 10X 还是 1X、地线夹为什么不能随便夹、差分测量怎么做，见<a href="./oscilloscope">示波器</a>。</p><h3 id="可调电源-有边界条件的能量" tabindex="-1">可调电源：有边界条件的能量 <a class="header-anchor" href="#可调电源-有边界条件的能量" aria-label="Permalink to &quot;可调电源：有边界条件的能量&quot;">​</a></h3><p>实验室直流可调电源（带恒压/恒流 CV-CC 指示与限流旋钮）是整个实验台最被低估的仪器。它的价值不在「能调电压」，而在于<strong>能设定电流上限</strong>：把限流设在预计电流的 1.2 倍，即使接反、短路、元件装错，电源也只输出这么多，功率落在电源的调整管上而不是你的元件上。5 V、100 mA 的限流下短路，也就 0.5 W 的发热。</p><p>选购时看三样：最大电压（30 V 够覆盖绝大多数弱电实验）、最大电流（3~5 A）、以及是否双路可串联。安全使用的细节在<a href="./bench">实验台与安全</a>。</p><h3 id="信号源-已知的激励" tabindex="-1">信号源：已知的激励 <a class="header-anchor" href="#信号源-已知的激励" aria-label="Permalink to &quot;信号源：已知的激励&quot;">​</a></h3><p>函数发生器提供正弦、方波、三角波，频率从 0.1 Hz 到 10 MHz 以上，幅度与直流偏置可调。它的作用是<strong>把实验中「未知」的那一半去掉</strong>：电路不动，只改变输入，看输出怎么变。测滤波器看幅频特性、测运放看频响、测比较器看阈值，全靠它。</p><p>入门实验只需要一台能输出单极性方波（用于 PWM）与 1 Hz~1 MHz 正弦的函数发生器；有任意波形（AWG）功能会方便很多，但不是必需。</p><h2 id="面包板与洞洞板" tabindex="-1">面包板与洞洞板 <a class="header-anchor" href="#面包板与洞洞板" aria-label="Permalink to &quot;面包板与洞洞板&quot;">​</a></h2><p><strong>面包板</strong>由一排排 5 孔的金属弹簧片组成，孔距 0.1 in（2.54 mm）。上下两条长排是电源轨（通常红正蓝负，<strong>但没有物理上的强制区分</strong>），中间每 5 孔为一组连通。它让你的手能在 30 秒内改一次拓扑，适合做的是：验证电路连接、试元件参数、给 MCU 拉线。</p><p>它不适合做的是：大电流（每个触点只按几百毫安设计，超过 500 mA 就该换洞洞板）、高频（触点电感与分布电容让 10 MHz 以上完全失真）、以及<strong>长期运行的电路</strong>（弹簧片会疲劳，接触电阻随时间上升）。</p><p><strong>洞洞板</strong>（万用板）是 0.1 in 间距的镀铜孔板，每孔有独立的焊盘，靠焊接与飞线建立连接。它把面包板上「压一下」的连接换成「焊死」的连接，好处是稳定、耐震、可长期通电；代价是改一次要拆焊。</p><p>两者的选择标准很简单：<strong>还在调参数，用面包板；参数定了要长期跑，焊到洞洞板上。</strong> 工艺细节（温度、助焊剂、虚焊、连锡、走线、拆焊）见<a href="./soldering">焊接与搭电路</a>。</p><h2 id="安全底线-六条不许商量的规则" tabindex="-1">安全底线：六条不许商量的规则 <a class="header-anchor" href="#安全底线-六条不许商量的规则" aria-label="Permalink to &quot;安全底线：六条不许商量的规则&quot;">​</a></h2><p>实验室事故的绝大多数都不是「学到了一个新知识」造成的，而是「省了一步」造成的。下面六条按顺序就是现场的正确动作：</p><ol><li><strong>强电与弱电分区。</strong> 220 V 插座、开关电源输入端与你的 3.3 V 逻辑电路之间，必须有物理距离（至少隔一块绝缘垫或一个电源模块）。强电区只有手和插头去，弱电区才有表笔与杜邦线。</li><li><strong>一切能量都经保险丝或限流进入电路。</strong> 电池供电串保险丝，台式电源用限流，USB 供电用带保险的 USB 模块。线径与保险丝额定值要匹配：1 A 的保险丝不保护 22 AWG 的线，只保护你自己。</li><li><strong>断电不等于没电。</strong> 大电容（开关电源、功放、闪光灯）拔电后仍可能存有上百伏高压。断电后先用 1 kΩ / 5 W 的电阻或专用放电棒放电，再用万用表确认电压降到 5 V 以下，才能碰。</li><li><strong>静电要防，防在接触之前。</strong> MOS 栅极、MCU 的 GPIO、示波器探头前端，在冬天的毛衣上走两步就能积累几千伏。摸板子前先摸一下接地的金属外壳。</li><li><strong>接地要唯一，漏保要有效。</strong> 示波器探头的鳄鱼夹就是大地，夹到非零电位点会通过示波器地线造成大电流。插座要确认有有效的接地与漏电保护，绝不可以用两孔插座或剪掉的第三脚。</li><li><strong>出问题先断电。</strong> 冒烟、异响、发烫、焦味，任何一条出现，第一动作都是拔插头或关总开关，不是「再测一下看是哪个元件烧了」。</li></ol><blockquote><p><strong>这里的「先断电」是有顺序的：断电 → 等 30 秒 → 放电 → 万用表验证 → 再分析。</strong> 跳过中间任何一步，分析的都是带电的电路。</p></blockquote><p>完整的器材清单与预算档位、强电弱电的分区方式、电容放电的做法、排查顺序，见<a href="./bench">实验台与安全</a>。强电侧的人身安全原理（摆脱电流、漏保动作值、保护接地与接零）在<a href="./../ee/07-control/safety">电工学 21 · 安全用电</a>里有完整推导。</p><h2 id="第一次上手-3-小时清单" tabindex="-1">第一次上手：3 小时清单 <a class="header-anchor" href="#第一次上手-3-小时清单" aria-label="Permalink to &quot;第一次上手：3 小时清单&quot;">​</a></h2><p>下面这张表是给「仪器是新的、人是新的」的情况设计的。每段时间都留了走神的余地，合计 200 min，实际通常在 2.5~3 h 完成。<strong>时间只作参考，卡住就停下查资料，不要为了「按时完成」而糊过去。</strong></p><table tabindex="0"><thead><tr><th>时段</th><th>做什么</th><th>完成判据</th></tr></thead><tbody><tr><td>0:00–0:20</td><td>清点器材，检查插座接地、漏保按钮，认清电源的电压/电流旋钮与 CV/CC 指示灯</td><td>能说出这台电源的限流设在哪里</td></tr><tr><td>0:20–1:05</td><td>万用表五档：测电池电压、测两个电阻串联与并联、测一段导线的通断、二极管档测一只 1N4148、三极管档量 β</td><td>串联读数等于两者之和、并联读数 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mstyle scriptlevel="0" displaystyle="true"><mfrac><mrow><msub><mi>R</mi><mn>1</mn></msub><msub><mi>R</mi><mn>2</mn></msub></mrow><mrow><msub><mi>R</mi><mn>1</mn></msub><mo>+</mo><msub><mi>R</mi><mn>2</mn></msub></mrow></mfrac></mstyle></mrow><annotation encoding="application/x-tex">\\dfrac{R_1R_2}{R_1+R_2}</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:2.1963em;vertical-align:-0.836em;"></span><span class="mord"><span class="mopen nulldelimiter"></span><span class="mfrac"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:1.3603em;"><span style="top:-2.314em;"><span class="pstrut" style="height:3em;"></span><span class="mord"><span class="mord"><span class="mord mathnormal" style="margin-right:0.0077em;">R</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:-0.0077em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">1</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">+</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0077em;">R</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:-0.0077em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">2</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span><span style="top:-3.23em;"><span class="pstrut" style="height:3em;"></span><span class="frac-line" style="border-bottom-width:0.04em;"></span></span><span style="top:-3.677em;"><span class="pstrut" style="height:3em;"></span><span class="mord"><span class="mord"><span class="mord mathnormal" style="margin-right:0.0077em;">R</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:-0.0077em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">1</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0077em;">R</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:-0.0077em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">2</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.836em;"><span></span></span></span></span></span><span class="mclose nulldelimiter"></span></span></span></span></span> 在公差内</td></tr><tr><td>1:05–1:35</td><td>面包板点亮 LED：5 V → 330 Ω → LED → 回电源负极，再反过来插一次</td><td>正向亮，反向不亮；先用 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>I</mi><mo>=</mo><mo stretchy="false">(</mo><mn>5</mn><mo>−</mo><msub><mi>U</mi><mi>F</mi></msub><mo stretchy="false">)</mo><mi mathvariant="normal">/</mi><mn>330</mn><mtext> </mtext><mi mathvariant="normal">Ω</mi></mrow><annotation encoding="application/x-tex">I = (5 - U_F)/330\\ \\Omega</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.0785em;">I</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mopen">(</span><span class="mord">5</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">−</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.109em;">U</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3283em;"><span style="top:-2.55em;margin-left:-0.109em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.1389em;">F</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mclose">)</span><span class="mord">/330</span><span class="mspace"> </span><span class="mord">Ω</span></span></span></span> 估电流（<span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><msub><mi>U</mi><mi>F</mi></msub></mrow><annotation encoding="application/x-tex">U_F</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8333em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.109em;">U</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3283em;"><span style="top:-2.55em;margin-left:-0.109em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.1389em;">F</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span> 取 2.0 V 时约 9.1 mA），再用万用表测 LED 两端约 1.9~2.1 V、电阻两端约 2.9~3.1 V</td></tr><tr><td>1:35–2:15</td><td>示波器自检：1 kHz 方波校准信号接探头，调补偿电容看到方正的方波；再用探头测 MCU 板上 8 MHz 时钟或一段杜邦线</td><td>方波无过冲（&gt;5% 幅度的尖峰算不合格），能读出频率</td></tr><tr><td>2:15–2:40</td><td>测 PWM：MCU 输出一路 1 kHz、占空比 25% 的 PWM，示波器上光标读出高电平时间</td><td>单位上读出约 250 μs 高电平、误差在 1% 内</td></tr><tr><td>2:40–3:05</td><td>焊两个焊点：先把一段导线焊到洞洞板的一个焊盘上，再用吸锡带拆下来</td><td>焊点成锥形、有金属光泽；拆下来后焊盘没有残锡</td></tr><tr><td>3:05–3:20</td><td>收拾：表笔归位、电源关断并旋回 0 V、拔掉所有电池、拍照记录这次的数据</td><td>桌面回到「只剩仪器」的状态</td></tr></tbody></table><blockquote><p><strong>为什么第一件事是「清点与安全」，而不是「直接测」</strong>：新手最容易在第一次就把表笔插进错误的插座、把电源限流放到最大、或者在一个没有接地的插座上开工。前 20 分钟花掉的成本，是避免后面 3 小时全部作废。</p></blockquote><h2 id="四个页面怎么读" tabindex="-1">四个页面怎么读 <a class="header-anchor" href="#四个页面怎么读" aria-label="Permalink to &quot;四个页面怎么读&quot;">​</a></h2><table tabindex="0"><thead><tr><th>页面</th><th>一句话</th><th>建议什么时候读</th></tr></thead><tbody><tr><td><a href="./multimeter">万用表</a></td><td>四件事（电压、电流、电阻、二极管）的接线与误判</td><td>买了万用表还没拆封时</td></tr><tr><td><a href="./oscilloscope">示波器</a></td><td>探头、带宽、触发、地线安全、PWM 与纹波</td><td>手上有会动的信号、需要看波形时</td></tr><tr><td><a href="./soldering">焊接与搭电路</a></td><td>从面包板到洞洞板的工艺</td><td>电路调通、准备固化的时候</td></tr><tr><td><a href="./bench">实验台与安全</a></td><td>器材清单、预算档位、用电安全与排查顺序</td><td>动手之前，以及任何一次「冒烟」之后</td></tr></tbody></table><h2 id="常见错误" tabindex="-1">常见错误 <a class="header-anchor" href="#常见错误" aria-label="Permalink to &quot;常见错误&quot;">​</a></h2><div class="tip custom-block"><p class="custom-block-title">错误 1 · 第一次上手就同时拆开所有仪器</p><p><strong>现象</strong>：三台仪器同时开机、同时接线，LED 不亮、示波器没波形、万用表读数乱跳，不知道是谁的问题。</p><p><strong>处理</strong>：一次只引入一台仪器，每引入一台就做一次「已知结果」的验证，万用表先测一节已知电压的电池，示波器先测自身的 1 kHz 校准方波。每台仪器都已验证之后，再组合起来。</p></div><div class="tip custom-block"><p class="custom-block-title">错误 2 · 用演示视频里的大电流实验器材起步</p><p><strong>现象</strong>：按视频接了 12 V 5 A 的电源去驱动电机或大功率 LED，第一分钟就冒烟。</p><p><strong>处理</strong>：第一阶段只使用不超过 12 V、限流 200 mA 的场景，并且优先用 USB 供电的 5 V/3.3 V 模块。等对万用表的读数有了信任，再放大电流与电压。</p></div><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to &quot;下一步&quot;">​</a></h2><ul><li>先看万用表：<a href="./multimeter">万用表</a></li><li>需要看波形：<a href="./oscilloscope">示波器</a></li><li>准备把电路焊死：<a href="./soldering">焊接与搭电路</a></li><li>布置自己的实验台：<a href="./bench">实验台与安全</a></li><li>强电侧的安全原理：<a href="./../ee/07-control/safety">电工学 21 · 安全用电</a></li></ul>',46))])}const f=n(o,[["render",h]]);export{v as __pageData,f as default};
